import {GAMES,ITEMS,ANIMALS,ICONS,STORIES,AUDIO_TEXTS,VERSION,MAX_LEVELS} from './content.js';
import {defaults,makeTrial,evaluate,walk,shouldAdvance,localDay,parseImport,addVisible,pathSolution} from './logic.js';
import * as storage from './storage.js';
const root=document.querySelector('#app');let data,saveError=false,installEvent,offlineReady=false;
let ui={page:'home',selected:['memory','helper'],gate:false,notice:''},trial=null,token=0,audio=null,audioDone=null,lastTick=performance.now(),lastSave=0,locked=false;
const uid=()=>crypto.randomUUID();const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const game=id=>GAMES.find(g=>g.id===id);const activeGame=()=>game(data.active.games[data.active.blockIndex]);
const $=s=>document.querySelector(s);const announce=s=>{$('#announcer').textContent=s;};
function notify(s){const n=document.createElement('div');n.className='notice';n.textContent=s;document.body.append(n);setTimeout(()=>n.remove(),5000);announce(s);}
function persist(){storage.checkpoint(data);storage.save(data).catch(()=>{if(!saveError){saveError=true;notify('Uložení se nepodařilo. Před zavřením zkuste export v rodičovském přehledu.');}});}
function stopAsync(){token++;if(audio){audio.pause();audio=null;}if(audioDone){audioDone();audioDone=null;}globalThis.speechSynthesis?.cancel();}
const delay=ms=>new Promise(r=>setTimeout(r,ms));
async function say(key){if(!data.settings.sound||!AUDIO_TEXTS[key])return;const mine=token;await new Promise(resolve=>{audioDone=resolve;audio=new Audio(`./assets/audio/${key}.wav`);audio.onended=()=>{audioDone=null;resolve();};audio.onerror=()=>{audioDone=null;resolve();};audio.play().catch(()=>{audioDone=null;resolve();});});if(mine!==token)return;}
function icon(x,cls=''){return `<span class="emoji ${cls}" aria-hidden="true">${x}</span>`;}
function shell(body,playing=false){root.innerHTML=`<main class="shell"><header class="topbar"><div class="brand"><img src="./assets/icon.svg" alt=""><span>Klidné hraní</span></div>${playing?'':`<button class="quiet" data-action="parent">Pro rodiče</button>`}</header>${body}</main>`;}
function home(){const a=data.active;const doneToday=data.sessions.some(s=>s.localDate===localDay());shell(`<section class="hello"><div><div class="eyebrow">Malé chvíle spolu</div><h1>Co si dnes zahrajeme?</h1><p class="muted">Vyberte spolu dvě hry. Na všechno je čas.</p></div><div class="status" id="offline-state">${offlineReady?'✓ Připraveno i bez internetu':'Připravuji hraní bez internetu…'}</div></section><section class="session-pick"><div class="pick-copy"><strong>${a?'Máte rozehranou návštěvu':doneToday?'Dnešní hraní už máte za sebou':`${ui.selected.length} ze 2 her vybrány`}</strong><p>${a?'Můžete se vrátit tam, kde jste skončili.':doneToday?'Teď můžete zkusit něco společně mimo obrazovku.':ui.selected.map(id=>game(id).name).join(' · ')||'Klepněte na obrázky her.'}</p></div>${a?'<button class="primary" data-action="resume-existing">Pokračovat spolu</button>':`<button class="primary" data-action="start" ${ui.selected.length!==2||doneToday?'disabled':''}>${doneToday?'Pro dnešek hotovo':'Jdeme si hrát'}</button>`}</section><section class="games" aria-label="Výběr her">${GAMES.map(g=>`<button data-action="select" data-id="${g.id}" aria-pressed="${ui.selected.includes(g.id)}" class="game-card ${g.color} ${ui.selected.includes(g.id)?'selected':''}">${ui.selected.includes(g.id)?`<span class="chosen">${ui.selected.indexOf(g.id)+1}</span>`:''}<span class="chip">${g.area}</span>${icon(g.emoji)}<div><h2>${g.name}</h2><p>${g.short}</p></div></button>`).join('')}</section><div class="footer-note"><span>Dvě krátké hry, mezi nimi odpočinek.</span><button class="quiet small" data-action="install">Přidat na tablet</button></div>`);}
function comfort(context){shell(`<section class="panel center"><div class="eyebrow">Můžeš jen ukázat</div><h1>Jak ti teď je?</h1><div class="comfort"><button data-action="comfort" data-value="okay" data-context="${context}">${icon('🙂','face')}Je mi dobře</button><button data-action="comfort" data-value="break" data-context="${context}">${icon('☕','face')}Chci pauzu</button><button data-action="comfort" data-value="end" data-context="${context}">${icon('🏠','face')}Chci skončit</button><button data-action="comfort" data-value="unsure" data-context="${context}">${icon('🤔','face')}Nevím</button></div><p class="muted">Každá odpověď je v pořádku.</p></section>`);}
function begin(choice){history.pushState({playing:true},'');data.active={id:uid(),localDate:localDay(),startedAt:new Date().toISOString(),status:'playing',games:[...ui.selected],blockIndex:0,blockLimitMs:data.settings.blockMs,blockVisibleMs:0,visibleMs:0,practiceDone:{},trialIndex:{},comfortBefore:{childChoice:choice,parentObservedSigns:[]},comfortAfter:{childChoice:'notAsked',parentObservedSigns:[]},breakUntil:null};ui.page='intro';persist();render();}
function intro(){const g=activeGame();shell(`<section class="panel center ${g.color}"><div class="eyebrow">${data.active.blockIndex+1}. hra ze dvou</div><div class="big-icon">${g.emoji}</div><h1>${g.name}</h1><p>${g.intro}</p><p class="muted">Nejdřív si to dvakrát zkusíme spolu.</p>${g.id==='helper'?`<details><summary>Společně poznáme obrázky</summary><div class="inline">${[...ITEMS,...ANIMALS].map(x=>`<button data-action="word" data-id="${x.id}">${x.emoji} ${x.name}</button>`).join('')}</div><p>Použijte jen slova, kterým dítě rozumí. Když některé nezná, nejdřív si je společně ukažte.</p></details>`:''}<div class="actions"><button class="quiet" data-action="intro-audio">🔊 Poslechnout</button><button class="primary" data-action="play">Zkusíme to</button><button class="quiet" data-action="stop">Končíme</button></div></section>`,true);}
function gameFrame(body){const g=activeGame();shell(`<section class="stage"><header class="game-header"><div><div class="eyebrow">${trial?.practice?'Zkoušíme spolu':g.area} · ${data.active.blockIndex+1}. hra</div><h1>${g.emoji} ${g.name}</h1></div><div class="toolbar"><button class="quiet" data-action="pause">Ⅱ Pauza</button><button class="quiet" data-action="stop">Končíme</button></div></header><div class="playfield">${body}</div><div class="actions"><button class="quiet" data-action="replay" ${trial?.phase==='feedback'||trial?.phase==='walking'?'disabled':''}>🔊 Ještě jednou</button><button class="quiet" data-action="hint" ${trial?.phase==='feedback'||trial?.phase==='rule'?'disabled':''}>Pomoz mi</button><button class="quiet" data-action="block-end">Pro tento blok hotovo</button></div></section>`,true);}
function scene(s,n){const edges={1:[0,361,723,1060,1448],2:[0,347,719,1077,1448],3:[0,349,698,1043,1448]}[s.atlas];const x=n*362+7,y=edges[s.row]+7,w=348,h=edges[s.row+1]-edges[s.row]-14;return `<div class="scene" role="img" aria-label="${esc(s.sentences[n])}" style="aspect-ratio:${w}/${h};background-image:url('./assets/story-atlas-${s.atlas}.png');background-size:${1086/w*100}% ${1448/h*100}%;background-position:${x/(1086-w)*100}% ${y/(1448-h)*100}%"></div>`;}
function showTrial(){if(!trial||ui.page!=='game')return;const t=trial;let body='';const hint=t.supportTypes.includes('visualCue')||t.practice;const disabled=t.phase!=='input'?'disabled':'';
 if(t.gameId==='memory')body=`<p class="instruction">${t.phase==='input'?'Teď ty. Kam šla liška?':'Podívej, kam jde liška.'}</p><div class="board two">${[0,1,2,3].map(n=>`<button class="tile house ${t.highlight===n?'active':''} ${t.responses.includes(n)?'sel':''}" data-action="answer" data-value="${n}" aria-label="Domeček ${n+1}" ${disabled}>🏠${t.highlight===n?'<span class="visitor">🦊</span>':''}</button>`).join('')}</div><div class="sequence">${t.responses.length} z ${t.target.length}</div>${hint&&t.phase==='input'?`<p class="muted">Společná nápověda: ${t.target.map(x=>x+1).join(' · ')}</p>`:''}`;
 if(t.gameId==='helper'){const step=t.target[t.responses.length]||t.target[0];body=`<p class="instruction">${t.target.map(p=>`Dej ${ITEMS.find(x=>x.id===p.item).name} ${ANIMALS.find(x=>x.id===p.animal).to}.`).join(' Potom ')}</p><div class="board two">${t.items.map(i=>`<button class="tile ${t.selected===i.id?'sel':''} ${hint&&step.item===i.id?'active':''}" data-action="item" data-id="${i.id}" aria-label="${i.name}" ${disabled}>${i.emoji}</button>`).join('')}</div><div class="board two">${t.animals.map(a=>`<button class="tile ${hint&&step.animal===a.id?'active':''}" data-action="recipient" data-id="${a.id}" aria-label="${a.name}" ${disabled||!t.selected?'disabled':''}>${a.emoji}</button>`).join('')}</div><p class="muted">${t.selected?'Teď vyber zvířátko.':'Nejdřív vyber předmět.'} ${t.responses.length?`Hotovo ${t.responses.length} z ${t.target.length}.`:''}</p>`;}
 if(t.gameId==='story')body=`<p class="instruction">Co se stalo první?</p><div class="story-cards">${t.options.map(n=>`<button class="story-card ${t.responses.includes(n)?'sel':''}" data-action="answer" data-value="${n}" ${disabled||t.responses.includes(n)?'disabled':''} aria-label="Obrázek ${n+1}: ${esc(t.story.sentences[n])}">${scene(t.story,n)}${t.responses.includes(n)?`<span class="order-mark">${t.responses.indexOf(n)+1}</span>`:''}</button>`).join('')}</div><p class="sequence">Vybráno ${t.responses.length} z ${t.target.length}</p>${hint?`<p class="muted">${t.target.map(n=>t.story.sentences[n]).join(' ')}</p>`:''}<button class="quiet" data-action="undo" ${disabled}>Vzít poslední zpět</button>`;
 if(t.gameId==='search'){const target=ICONS.find(x=>x.id===t.target);body=`<p class="instruction">Najdi stejný obrázek.</p><div class="target" aria-label="Hledáme ${target.name}">${target.emoji}</div><div class="board ${t.options.length>4?'three':'two'}">${t.options.map(x=>`<button class="tile ${hint&&x.id===t.target?'active':''}" data-action="answer" data-value="${x.id}" aria-label="${x.name}" ${disabled}>${x.emoji}</button>`).join('')}</div>`;}
 if(t.gameId==='stop')body=`<p class="instruction">${t.phase==='input'?(t.go?'Zelená: klepni.':'Červená: počkej.'):'Připrav se.'}</p>${t.phase==='input'?`<div class="signal ${t.go?'go':'stop'}" aria-label="${t.go?'Klepni':'Počkej'}">${t.go?'☝️':'✋'}</div>`:'<div class="breathing">🚂</div>'}<button class="primary" data-action="tap" ${disabled||t.tapped?'disabled':''}>${t.tapped?'Klepnutí zaznamenáno':'Klepnout'}</button>`;
 if(t.gameId==='sort')body=`<p class="instruction">${t.rule==='color'?'Třídíme podle barvy.':'Třídíme podle tvaru.'}</p><p class="chip">${t.rule==='color'?'🔵 Barva':'■ Tvar'}</p><div style="padding:22px"><span class="shape ${t.color} ${t.shape}" aria-label="${t.color==='blue'?'Modrý':'Žlutý'} ${t.shape==='circle'?'kruh':'čtverec'}"></span></div><div class="board two">${t.options.map(o=>`<button class="tile bucket ${hint&&o===t.target?'active':''}" data-action="answer" data-value="${o}" aria-label="${o}" ${disabled}><span class="shape ${t.rule==='color'?o:'blue'} ${t.rule==='shape'?o:'square'}"></span><span class="label">${({blue:'Modrá',gold:'Žlutá',circle:'Kruhy',square:'Čtverce'})[o]}</span></button>`).join('')}</div>`;
 if(t.gameId==='path'){body=`<p class="instruction">${t.maxSteps} kroky k pokladu</p><div class="path-grid">${Array.from({length:9},(_,n)=>`<div class="path-cell ${t.obstacles.includes(n)?'rock':''}">${t.walkPos===n?'🦊':t.target===n?'🎁':t.start===n&&t.walkPos==null?'🦊':t.obstacles.includes(n)?'🪨':''}</div>`).join('')}</div><div class="sequence">${t.responses.map(x=>({up:'↑',down:'↓',left:'←',right:'→'})[x]).join('　')||'Vyber šipky'}</div><div class="arrow-buttons">${['up','left','right','down'].map(x=>`<button data-action="move" data-value="${x}" aria-label="${({up:'Nahoru',left:'Doleva',right:'Doprava',down:'Dolů'})[x]}" ${disabled||t.responses.length>=t.maxSteps?'disabled':''}>${({up:'↑',left:'←',right:'→',down:'↓'})[x]}</button>`).join('')}</div><div class="actions"><button class="quiet" data-action="undo">Zpět</button><button class="primary" data-action="walk" ${disabled||!t.responses.length?'disabled':''}>Zkusit cestu</button></div>${hint?'<p class="muted">Společně ukažte cestu prstem, než vyberete šipky.</p>':''}`;}
 if(t.gameId==='rhythm')body=`<p class="instruction">${t.phase==='input'?'Odložte tablet a zopakujte rytmus.':'Poslouchej a dívej se.'}</p><div class="rhythm-seq">${t.target.map((x,n)=>`<div class="rhythm-beat ${t.highlight===n?'active':''}">${x==='clap'?'👏':'🦵'}</div>`).join('')}</div><p class="muted">👏 tlesknutí · 🦵 dotek stehen</p>${t.phase==='input'?`<div class="actions"><button class="primary" data-action="rhythm-result" data-value="independent">Zopakoval samostatně</button><button class="quiet" data-action="rhythm-result" data-value="supported">Zkusili jsme to spolu</button><button class="quiet" data-action="rhythm-result" data-value="notRated">Nehodnotíme</button></div>`:''}`;
 if(t.phase==='feedback'){body+=`<div class="feedback ${t.correctFirst===false?'try':''}"><span>${t.correctFirst===false?'Zkusili jsme to. Ukážeme si to spolu.':t.gameId==='rhythm'?'Děkujeme za společný rytmus.':'Povedlo se.'}</span><button class="primary" data-action="next">Další obrázek</button></div>`;if(t.correctFirst===false)body+=`<div class="hint">${solution(t)}</div>`;if(t.gameId==='story')body+=`<div class="hint"><p><strong>Společné povídání</strong></p><button class="quiet" data-action="story-audio">🔊 Příběh a otázka</button><p>${esc(t.level===3?t.story.question:t.story.simpleQuestion)}</p><p>${esc(t.story.sentences.join(' '))}</p><div class="actions">${['Ukázal','Odpověděl slovem','Odpověděl větou','S pomocí','Nehodnoceno'].map(x=>`<button class="quiet" data-action="language" data-value="${x}" ${t.language===x?'aria-pressed="true"':''}>${x}</button>`).join('')}</div></div>`;}
 gameFrame(body);
}
function solution(t){if(t.gameId==='memory')return `Domečky: ${t.target.map(n=>n+1).join(' · ')}.`;if(t.gameId==='helper')return t.target.map(p=>`${ITEMS.find(x=>x.id===p.item).emoji} patří ${ANIMALS.find(x=>x.id===p.animal).emoji}`).join(' · ');if(t.gameId==='story')return t.target.map(n=>t.story.sentences[n]).join(' ');if(t.gameId==='search')return `Hledali jsme ${ICONS.find(x=>x.id===t.target).emoji}.`;if(t.gameId==='stop')return t.go?'Na zelený signál klepneme.':'Na červený signál necháme ruce v klidu.';if(t.gameId==='sort')return `Pravidlo: ${t.rule==='color'?'barva':'tvar'}. Správně: ${({blue:'modrá',gold:'žlutá',circle:'kruh',square:'čtverec'})[t.target]}.`;if(t.gameId==='path')return 'Zkusíme '+pathSolution(t).map(m=>({up:'nahoru',down:'dolů',left:'doleva',right:'doprava'})[m]).join(', ')+'.';return 'Zkusíme to spolu.';}
async function present(){const t=trial,mine=token;t.phase='show';t.responses=[];t.highlight=null;t.tapped=false;t.firstTapAt=null;t.selected=null;t.walkPos=null;showTrial();
 if(t.gameId==='memory'){await say('look');for(const n of t.target){if(mine!==token)return;t.highlight=n;showTrial();await delay(1500);if(mine!==token)return;t.highlight=null;showTrial();await delay(500);}if(mine!==token)return;await say('ready');}
 else if(t.gameId==='helper'){for(let n=0;n<t.target.length;n++){if(mine!==token)return;if(n)await say('then');const p=t.target[n];await say(`give-${p.item}-${p.animal}`);}}
 else if(t.gameId==='story')await say('intro-story');
 else if(t.gameId==='search')await say('same');
 else if(t.gameId==='sort'){await say(t.rule);if(t.level===3&&t.index%5===0){if(mine!==token)return;t.phase='rule';gameFrame(`<div class="big-icon">${t.rule==='color'?'🔵':'■'}</div><h2>Teď třídíme podle ${t.rule==='color'?'barvy':'tvaru'}.</h2><p>Nejdřív si nové pravidlo společně ukážeme.</p><button class="primary" data-action="rule-ready">Rozumíme, zkusíme</button>`);return;}}
 else if(t.gameId==='path')await say('path');
 else if(t.gameId==='rhythm'){await say('rhythm');for(let n=0;n<t.target.length;n++){if(mine!==token)return;t.highlight=n;showTrial();beep(t.target[n]==='clap'?660:280);await delay(750);if(mine!==token)return;t.highlight=null;showTrial();await delay(350);}}
 if(mine!==token)return;t.phase='input';t.inputAt=performance.now();showTrial();
 if(t.gameId==='stop'){await delay(3000);if(mine!==token||t.phase!=='input')return;finish(t.tapped);}
}
function beep(hz){if(!data.settings.sound)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)();const o=ctx.createOscillator(),gain=ctx.createGain();o.type='sine';o.frequency.value=hz;gain.gain.setValueAtTime(.12,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.16);o.connect(gain);gain.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.17);o.onended=()=>ctx.close();}catch{}}
function newTrial(){stopAsync();const a=data.active,id=activeGame().id;const practice=(a.practiceDone[id]||0)<2;const index=a.trialIndex[id]||0;const contentIndex=data.trials.filter(t=>t.gameId===id&&t.completed&&!t.practice).length;trial=makeTrial(id,data.settings.levels[id],practice,Math.random,practice?(a.practiceDone[id]||0):(id==='story'?contentIndex:index));if(id==='memory'){const last=data.trials.filter(t=>t.gameId===id&&t.target).at(-1);if(JSON.stringify(last?.target)===JSON.stringify(trial.target))trial.target=trial.target.map(n=>(n+1)%4);}trial.index=index;trial.id=uid();trial.responses=[];ui.page='game';persist();present();}
function finish(response,manual=null){const t=trial;if(!t||t.phase!=='input')return;stopAsync();t.correctFirst=evaluate(t,response);t.phase='feedback';t.firstResponse=structuredClone(response);const entry={id:t.id,sessionId:data.active.id,gameId:t.gameId,contentId:t.contentId,level:t.level,practice:t.practice,completed:true,correctFirst:t.correctFirst,supportTypes:[...t.supportTypes],localDate:localDay(),responseMs:t.inputAt?Math.round((t.firstTapAt||performance.now())-t.inputAt):null,firstResponse:t.firstResponse,target:t.target,manualResult:manual,language:null,invalidReason:null};data.trials.push(entry);if(t.practice)data.active.practiceDone[t.gameId]=(data.active.practiceDone[t.gameId]||0)+1;else data.active.trialIndex[t.gameId]=(data.active.trialIndex[t.gameId]||0)+1;persist();showTrial();say(t.correctFirst===false?'retry':'correct');}
function pause(reason='requested'){if(!data.active||data.active.status==='done')return;stopAsync();if(trial&&trial.phase!=='feedback'){data.trials.push({id:trial.id,sessionId:data.active.id,gameId:trial.gameId,level:trial.level,localDate:localDay(),practice:trial.practice,completed:false,correctFirst:null,supportTypes:trial.supportTypes,invalidReason:reason});trial=null;}data.active.status='paused';ui.page='paused';persist();render();}
function invalidateTrial(reason){if(trial&&trial.phase!=='feedback'){data.trials.push({id:trial.id,sessionId:data.active.id,gameId:trial.gameId,level:trial.level,localDate:localDay(),practice:trial.practice,completed:false,correctFirst:null,supportTypes:[...trial.supportTypes],invalidReason:reason});}trial=null;}
function blockEnd(){if(!data.active)return;stopAsync();invalidateTrial('block-end');if(data.active.blockIndex===1){endSession('completed');return;}data.active.status='break';data.active.breakUntil=Date.now()+60000;ui.page='break';persist();render();say('break');}
function endSession(reason='requested'){if(!data.active)return;stopAsync();invalidateTrial(reason);data.active.status='done';data.active.stopReason=reason;data.active.endedAt=new Date().toISOString();ui.page='after';persist();render();}
function archive(choice){const a=data.active;a.comfortAfter.childChoice=choice;data.sessions.push(structuredClone(a));data.active=null;ui.lastSession=a;ui.page='summary';persist();render();say('end');}
function rest(){const a=data.active,left=Math.max(0,Math.ceil((a.breakUntil-Date.now())/1000));shell(`<section class="panel center"><div class="eyebrow">Chvilka odpočinku</div><div class="breathing">🌤️</div><h1>Teď se rozhlédneme.</h1><p>Odložte tablet. Podívejte se do dálky nebo se spolu protáhněte.</p><p class="muted" id="break-count">${left?'Další hra bude připravená za '+left+' s.':'Další hra je připravená, pokud chcete.'}</p><div class="actions"><button class="primary" data-action="after-break" id="break-continue" ${left?'disabled':''}>Rodič: můžeme dál</button><button class="quiet" data-action="stop">Pro dnešek stačí</button></div></section>`,true);}
function paused(){shell(`<section class="panel center"><div class="big-icon">☕</div><h1>Máme pauzu.</h1><p>Nemusíš říkat proč. Pokračovat můžeme, až budete chtít.</p><div class="actions"><button class="primary" data-action="resume">Rodič: pokračovat</button><button class="quiet" data-action="comfort-pause">Jak mi je</button><button class="quiet" data-action="symptom">Bolest nebo potíže s viděním</button><button class="quiet" data-action="stop">Končíme</button></div></section>`,true);}
function summary(){const a=ui.lastSession;const ts=data.trials.filter(t=>t.sessionId===a.id&&!t.practice&&t.completed);shell(`<section class="panel center"><div class="big-icon">🌟</div><h1>Máme hotovo.</h1><p>Děkujeme za společné hraní.</p><p class="muted">${ts.length} dokončených pokusů · ${Math.round(a.visibleMs/6000)/10} min společně</p>${a.stopReason==='symptom'?'<p class="warning">Dnes už nepokračujte. Při opakovaných potížích se poraďte s vyšetřujícím pracovištěm.</p>':''}<div class="hint"><strong>Ještě něco bez tabletu?</strong><p>${game(a.games[a.blockIndex]).offline}</p></div><div class="actions"><button class="primary" data-action="home">Zpět na hry</button><button class="quiet" data-action="parent">Přehled pro rodiče</button></div></section>`);}
function gate(){shell(`<section class="panel center"><div class="big-icon">👋</div><h1>Chvilka pro rodiče</h1><p>Pro otevření přehledu podržte tlačítko dvě sekundy.</p><button class="primary" id="parent-hold">Podržet pro otevření</button><p class="muted">Také lze podržet mezerník. Tato brána není zabezpečení zařízení.</p><button class="quiet" data-action="home">Zpět</button></section>`);let timer;const b=$('#parent-hold');const down=e=>{if(e.type==='keydown'&&e.code!=='Space'&&e.code!=='Enter')return;e.preventDefault();clearTimeout(timer);timer=setTimeout(()=>{ui.gate=true;ui.page='parent';render();},2000);};const up=()=>clearTimeout(timer);b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointerleave',up);b.addEventListener('pointercancel',up);b.addEventListener('keydown',e=>{if(!e.repeat)down(e);});b.addEventListener('keyup',up);}
function parent(){const counts=GAMES.map(g=>{const ts=data.trials.filter(t=>t.gameId===g.id&&t.completed&&!t.practice&&!t.invalidReason);return {g,ts,independent:ts.filter(t=>t.correctFirst===true&&!t.supportTypes.length).length};});shell(`<section class="panel wide"><div class="inline" style="justify-content:space-between"><h1>Pro rodiče</h1><button class="quiet" data-action="home">Zpět na hry</button></div><p class="muted">Sledujeme procvičování. Výsledky neurčují diagnózu ani zlepšení soustředění mimo hru.</p><div class="settings-grid"><div class="setting"><label for="duration">Délka jednoho bloku</label><select id="duration"><option value="120000" ${data.settings.blockMs===120000?'selected':''}>2 minuty</option><option value="180000" ${data.settings.blockMs===180000?'selected':''}>3 minuty</option></select><p class="muted">Dva bloky, mezi nimi alespoň minuta mimo displej. Délku nezvyšujte současně s obtížností.</p></div><div class="setting"><label for="sound">Hlasové pokyny</label><select id="sound"><option value="on" ${data.settings.sound?'selected':''}>Zapnuté</option><option value="off" ${!data.settings.sound?'selected':''}>Vypnuté · čte rodič</option></select><button class="quiet" data-action="install">Přidat aplikaci na tablet</button></div>${GAMES.map(g=>`<div class="setting"><label for="level-${g.id}">${g.emoji} ${g.name}</label><select data-level="${g.id}" id="level-${g.id}">${Array.from({length:MAX_LEVELS[g.id]},(_,i)=>i+1).map(n=>`<option value="${n}" ${data.settings.levels[g.id]===n?'selected':''}>Úroveň ${n}${n===1?' · začátek':''}</option>`).join('')}</select>${shouldAdvance(data.trials,g.id,data.settings.levels[g.id])?'<p>Poslední pokusy naznačují, že můžete příště zkusit o stupeň více, pokud je dítě v pohodě.</p>':''}</div>`).join('')}</div><div class="actions"><button class="primary" data-action="save-settings">Uložit nastavení</button></div><h2>Procvičování v tomto zařízení</h2><div class="table-wrap"><table><thead><tr><th>Hra</th><th>Pokusy</th><th>Správně bez pomoci</th><th>S podporou</th></tr></thead><tbody>${counts.map(({g,ts,independent})=>`<tr><td>${g.name}</td><td>${ts.length}</td><td>${g.id==='rhythm'?'Hodnotí rodič':independent}</td><td>${ts.filter(t=>t.supportTypes.length).length}</td></tr>`).join('')}</tbody></table></div><h2>Co pozorujete mimo aplikaci</h2><p class="muted">Například počet připomenutí při podobném úkolu nebo zvládnutí známého pokynu. Nehlášená bolest není potvrzením pohodlí.</p><label for="observation">Krátká poznámka</label><textarea id="observation" maxlength="1000" placeholder="Co se dařilo? Kdy chtěl přestat? Co jste skutečně viděli?"></textarea><button class="quiet" data-action="observation">Uložit pozorování</button>${data.observations.slice(-4).reverse().map(o=>`<p><strong>${esc(o.localDate)}</strong> ${esc(o.note)}</p>`).join('')}<h2>Poslední návštěvy</h2>${data.sessions.length?data.sessions.slice(-5).reverse().map(s=>`<p>${esc(s.localDate)} · ${s.games.map(id=>game(id)?.name||'Hra').join(' a ')} · dítě: ${esc(({okay:'je mi dobře',break:'chci pauzu',end:'chci skončit',unsure:'nevím',notAsked:'neptali jsme se'})[s.comfortAfter?.childChoice]||'nezaznamenáno')}</p>`).join(''):'<p>Zatím žádná dokončená návštěva.</p>'}<details><summary>Data, soukromí a záloha</summary><p>Výsledky jsou jen v tomto zařízení. Vymazání dat prohlížeče je může odstranit. Rodičovská brána není šifrování. Aplikace nepoužívá reklamy, mikrofon ani analytiku.</p><div class="actions"><button class="quiet" data-action="export">Export JSON</button><button class="quiet" data-action="csv">Export CSV</button><label class="quiet">Import zálohy <input type="file" id="import" accept="application/json,.json"></label><button class="quiet" data-action="clear">Smazat data zařízení</button></div></details><details><summary>Domácí režim a význam her</summary><p>Začněte třikrát týdně. Doplňte společným příběhem, krátkými známými pokyny a hrou venku. Při nepohodě skončete; dítě ji nemusí přesně popsat. Oční cvičení provádějte podle vlastního předpisu pracoviště.</p><p>Zlepšení herního skóre samo neprokazuje přenos do běžného života. Jednotlivé hry nejsou léčbou akomodačního excesu ani diagnostickým testem.</p></details><details><summary>Nová návštěva ve stejný den</summary><p>Výchozí plán je jedna návštěva denně. Tuto možnost používejte pro kontrolu aplikace dospělým, ne k prodlužování dětského tréninku.</p><button class="quiet" data-action="adult-restart">Připravit návštěvu pro kontrolu dospělým</button></details><p class="credits">Klidné hraní ${VERSION} · ilustrace vytvořené pro tento projekt · český hlas Microsoft Jakub · ikony Unicode.</p></section>`);}
function render(){switch(ui.page){case 'home':home();break;case 'before':comfort('before');break;case 'after':comfort('after');break;case 'comfort-pause':comfort('pause');break;case 'intro':intro();break;case 'game':showTrial();break;case 'break':rest();break;case 'paused':paused();break;case 'summary':summary();break;case 'gate':gate();break;case 'parent':ui.gate?parent():gate();break;case 'unsure':shell(`<section class="panel center"><h1>Můžeme si dát čas.</h1><p>Nemusíš vědět proč. S rodičem se rozhodněte, jestli chcete zkusit krátký blok, nebo dnes skončit.</p><div class="actions"><button class="primary" data-action="unsure-go">Rodič: zkusíme krátce</button><button class="quiet" data-action="unsure-end">Dnes skončíme</button></div></section>`);}}
async function act(action,b){const value=b?.dataset.value,id=b?.dataset.id;
 if(action==='select'){ui.selected=ui.selected.includes(id)?ui.selected.filter(x=>x!==id):ui.selected.length<2?[...ui.selected,id]:[ui.selected[1],id];home();}
 if(action==='start'){if(data.active||data.sessions.some(s=>s.localDate===localDay())||ui.selected.length!==2)return;ui.page='before';render();}
 if(action==='comfort'){const context=b.dataset.context;if(context==='after'){archive(value);return;}if(context==='before'){if(value==='okay')begin(value);else if(value==='unsure'){ui.unsureContext='before';ui.page='unsure';render();}else{ui.page='home';render();notify('Dnes nemusíme hrát.');}}else{data.active.comfortAfter.childChoice=value;if(value==='end')endSession();else if(value==='okay'){ui.page='paused';render();}else if(value==='unsure'){ui.unsureContext='pause';ui.page='unsure';render();}else{ui.page='paused';render();}persist();}}
 if(action==='unsure-go'){if(ui.unsureContext==='before')begin('unsure');else{ui.page='paused';render();}}
 if(action==='unsure-end'){if(data.active)endSession();else{ui.page='home';render();}}
 if(action==='play')newTrial();
 if(action==='intro-audio'){stopAsync();say('intro-'+activeGame().id);}
 if(action==='word'){stopAsync();say('word-'+id);}
 if(action==='answer'&&trial?.phase==='input'){let v=['memory','story'].includes(trial.gameId)?Number(value):value;if(['memory','story'].includes(trial.gameId)){trial.responses.push(v);if(trial.responses.length===trial.target.length)finish(trial.responses);else showTrial();}else finish(v);}
 if(action==='item'&&trial?.phase==='input'){trial.selected=id;showTrial();}
 if(action==='recipient'&&trial?.phase==='input'&&trial.selected){trial.responses.push({item:trial.selected,animal:id});trial.selected=null;if(trial.responses.length===trial.target.length)finish(trial.responses);else showTrial();}
 if(action==='tap'&&trial?.phase==='input'){trial.tapped=true;trial.firstTapAt=performance.now();showTrial();}
 if(action==='move'&&trial?.phase==='input'&&trial.responses.length<trial.maxSteps){trial.responses.push(value);showTrial();}
 if(action==='undo'&&trial?.phase==='input'){trial.responses.pop();if(!trial.supportTypes.includes('parentHelp'))trial.supportTypes.push('parentHelp');showTrial();}
 if(action==='walk'&&trial?.phase==='input'){const t=trial,mine=token;t.phase='walking';t.walkPos=t.start;showTrial();let steps=[];for(const m of t.responses){steps.push(m);const r=walk(t.start,steps,t.obstacles);t.walkPos=r.pos;showTrial();await delay(650);if(mine!==token)return;if(!r.valid)break;}t.phase='input';finish(t.responses);}
 if(action==='rhythm-result'&&trial?.phase==='input'){if(value==='supported')trial.supportTypes.push('parentHelp');finish(null,value);}
 if(action==='rule-ready'&&trial?.phase==='rule'){trial.phase='input';trial.inputAt=performance.now();showTrial();}
 if(action==='next'&&trial?.phase==='feedback'){const xs=data.trials.filter(t=>t.sessionId===data.active.id&&t.gameId===trial.gameId&&t.completed).slice(-3);if(xs.length===3&&xs.every(t=>t.correctFirst===false)){pause('three-errors');notify('Zkusme pauzu a společně ověřme zadání.');}else newTrial();}
 if(action==='replay'&&trial&&trial.phase!=='feedback'&&trial.phase!=='walking'){stopAsync();if(!trial.supportTypes.includes('audioReplay'))trial.supportTypes.push('audioReplay');present();}
 if(action==='hint'&&trial&&trial.phase!=='feedback'&&trial.phase!=='rule'){if(!trial.supportTypes.includes('visualCue'))trial.supportTypes.push('visualCue');showTrial();}
 if(action==='story-audio'&&trial?.phase==='feedback'){stopAsync();const mine=token;const t=trial;(async()=>{for(let n=0;n<3;n++){if(mine!==token)return;await say(t.story.id+'-'+n);}if(mine===token)await say(t.story.id+(t.level===3?'-q':'-simple'));})();}
 if(action==='language'&&trial?.phase==='feedback'){trial.language=value;const record=data.trials.find(t=>t.id===trial.id);if(record)record.language=value;persist();showTrial();}
 if(action==='pause')pause();
 if(action==='resume-existing'){const a=data.active;if(a.status==='done')ui.page='after';else if(a.status==='break')ui.page='break';else{a.status='paused';ui.page='paused';}render();}
 if(action==='resume'){data.active.status='playing';if(data.active.blockVisibleMs>=data.active.blockLimitMs)blockEnd();else{ui.page='intro';render();}persist();}
 if(action==='after-break'&&data.active&&Date.now()>=data.active.breakUntil){data.active.blockIndex=1;data.active.blockVisibleMs=0;data.active.status='playing';ui.page='intro';persist();render();}
 if(action==='block-end')blockEnd();
 if(action==='stop')endSession();
 if(action==='comfort-pause'){ui.page='comfort-pause';render();}
 if(action==='symptom'){data.active.comfortAfter.parentObservedSigns.push('reportedVisualDiscomfort');endSession('symptom');}
 if(action==='home'){stopAsync();ui.gate=false;ui.page='home';render();}
 if(action==='parent'){stopAsync();if(data.active?.status==='playing')pause('parent');ui.page=ui.gate?'parent':'gate';render();}
 if(action==='save-settings'){if(data.active){notify('Nastavení změňte po dokončení rozehrané návštěvy.');return;}data.settings.blockMs=Number($('#duration').value);data.settings.sound=$('#sound').value==='on';document.querySelectorAll('[data-level]').forEach(x=>data.settings.levels[x.dataset.level]=Number(x.value));persist();notify('Nastavení uložené pro příští hraní.');}
 if(action==='observation'){const note=$('#observation').value.trim();if(note){data.observations.push({id:uid(),localDate:localDay(),note:note.slice(0,1000)});persist();parent();}}
 if(action==='export')download(JSON.stringify(data,null,2),'klidne-hrani-'+localDay()+'.json','application/json');
 if(action==='csv'){const safe=x=>'"'+String(x??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"';const rows=[['typ','datum','hra','spravne_prvni','podpora','poznamka'],...data.trials.map(t=>['pokus',t.localDate,t.gameId,t.correctFirst??'',t.supportTypes.join('|'),t.practice?'nácvik':'']),...data.observations.map(o=>['pozorování',o.localDate,'','','',o.note])];download('\ufeff'+rows.map(r=>r.map(safe).join(';')).join('\r\n'),'klidne-hrani-'+localDay()+'.csv','text/csv;charset=utf-8');}
 if(action==='clear'&&confirm('Opravdu smazat všechny výsledky a nastavení v tomto zařízení? Nejdřív si můžete stáhnout zálohu.')){stopAsync();await storage.clear();data=defaults();ui.page='parent';render();notify('Data zařízení byla smazána.');}
 if(action==='adult-restart'&&confirm('Nová návštěva je určena pro kontrolu dospělým. Pokračovat?')){if(data.active){notify('Nejprve dokončete rozehranou návštěvu.');return;}begin('notAsked');}
 if(action==='install'){if(installEvent){await installEvent.prompt();installEvent=null;}else notify('Na Androidu otevřete aplikaci v Chrome a v nabídce ⋮ zvolte Instalovat aplikaci nebo Přidat na plochu.');}
}
function download(text,name,mime){const url=URL.createObjectURL(new Blob([text],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled||(locked&&!['pause','stop','block-end','parent'].includes(b.dataset.action)))return;locked=true;try{await act(b.dataset.action,b);}catch(err){console.error(err);notify('Tento krok se nepodařil. Zkuste pauzu a návrat.');}finally{locked=false;}});
document.addEventListener('change',async e=>{if(e.target.id==='import'&&e.target.files?.[0]){try{const next=parseImport(await e.target.files[0].text());if(confirm('Nahradit místní data touto zálohou? Rozehraná návštěva se neobnoví.')){stopAsync();data=next;persist();parent();notify('Záloha obnovena.');}}catch(err){notify(err.message);}e.target.value='';}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&data?.active?.status==='playing')pause('hidden');lastTick=performance.now();});
window.addEventListener('pagehide',()=>{stopAsync();if(data)storage.checkpoint(data);});
let resize;window.addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(()=>{if(data?.active?.status==='playing'&&ui.page==='game')pause('resize');},200);});
window.addEventListener('popstate',()=>{if(data?.active?.status==='playing'){pause('back');history.pushState({playing:true},'');}else if(data?.active&&ui.page!=='home'){ui.page='home';render();}});
setInterval(()=>{const now=performance.now(),delta=now-lastTick;lastTick=now;if(!data)return;if(data.active?.status==='playing'&&!document.hidden){addVisible(data.active,delta);if(now-lastSave>500){persist();lastSave=now;}if(data.active.blockVisibleMs>=data.active.blockLimitMs){const excess=data.active.blockVisibleMs-data.active.blockLimitMs;data.active.visibleMs-=excess;data.active.blockVisibleMs=data.active.blockLimitMs;blockEnd();}}if(ui.page==='break'&&data.active){const left=Math.max(0,Math.ceil((data.active.breakUntil-Date.now())/1000));const p=$('#break-count');if(p)p.textContent=left?'Další hra bude připravená za '+left+' s.':'Další hra je připravená, pokud chcete.';const b=$('#break-continue');if(b)b.disabled=left>0;}},250);
try{data=await storage.load();if(data.active?.status==='playing'){data.active.status='paused';persist();}if(data.active)history.pushState({playing:true},'');render();}catch(err){shell(`<section class="panel"><h1>Uložení není dostupné</h1><p>${esc(err.message)}</p><p>Zkuste běžné okno prohlížeče s povoleným místním úložištěm. Existující data jsme nepřepsali.</p><button class="quiet" data-action="install">Jak aplikaci nainstalovat</button></section>`);}
if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(async()=>{await navigator.serviceWorker.ready;offlineReady=true;if(ui.page==='home')home();}).catch(()=>{offlineReady=false;const p=$('#offline-state');if(p)p.textContent='Offline stažení zatím není dokončené.';});}
